<?phpif (!defined('BASEPATH')) {	exit('No direct script access allowed');}include_once APPPATH . '/modules/layout/controllers/Layout.php';class Rows extends Layout {	private $_path = '';	private $_module_slug = 'shops/items';	//private $_shops_size = '336x410';	private $_shops_size = NULL;	private $_tag = 'shop';	private $_allowed_field = array('status', 'inhome', 'is_featured', 'is_new', 'is_bestseller');	function __construct() {		parent::__construct();		$this->load->library('form_validation');		$this->_data['breadcrumbs_module_name'] = 'Sản phẩm';		$this->_data['module_slug'] = $this->_module_slug;		$this->_path = get_module_path('shops');		$this->_shops_size = $this->config->item('shops_sizes');		$shops_sizes = $this->config->item('shops_sizes');		$this->_data['shops_size'] = $shops_sizes['thumb'];	}	function admin_ajax_change_field() {		if (!$this->input->is_ajax_request()) {			exit('No direct script access allowed');		}		$post = $this->input->post();		if (!empty($post)) {			$value = $this->input->post('value');			$id = $this->input->post('id');			$field = $this->input->post('field');			$massage_success = $this->input->post('massage_success');			$massage_warning = $this->input->post('massage_warning');			$data = array(				$field => $value,			);			if (!in_array($field, $this->_allowed_field)) {				$notify_type = 'danger';				$notify_content = 'Trường này không tồn tại!';			} else if ($this->M_shops_rows->update($id, $data)) {				if ($value == 1) {					$notify_type = 'success';					$notify_content = $massage_success;				} else {					$notify_type = 'warning';					$notify_content = $massage_warning;				}			} else {				$notify_type = 'danger';				$notify_content = 'Dữ liệu chưa lưu!';			}			$this->set_notify_admin($notify_type, $notify_content);			$this->load->view('layout/notify-ajax', NULL);		} else {			redirect(base_url());		}	}	public function gets_item_field($field = '', $number = 3) {		if ((trim($field) == '') || !in_array($field, $this->_allowed_field)) {			return null;		}		$args = $this->default_args();		$args[$field] = 1;		if ($number > 0) {			$rows = $this->M_shops_rows->gets($args, $number, 0);		} else {			$rows = $this->M_shops_rows->gets($args);		}		return $rows;	}	function default_args() {		$order_by = array(			'order' => 'ASC',			'title' => 'ASC',			'addtime' => 'DESC',			'edittime' => 'DESC',		);		$args = array();		$args['order_by'] = $order_by;		return $args;	}	function counts($args) {		return $this->M_shops_rows->counts($args);	}	function get($id, $alias = '') {		$row = $this->M_shops_rows->get($id, $alias);		if (!empty($row) && isset($row['id'])) {			$row['options'] = $this->get_options($row['id']);		}		return $row;	}	function gets($options = array()) {		$default_args = $this->default_args();		if (is_array($options) && !empty($options)) {			$args = array_merge($default_args, $options);		} else {			$args = $default_args;		}		return $this->M_shops_rows->gets($args);	}	function get_options($id = 0) {		return modules::run('shops/other/gets', array('product' => $id, 'is_temp' => 0));	}	function get_max_order() {		$args = $this->default_args();		$order_by = array(			'order' => 'DESC',		);		$args['order_by'] = $order_by;		$perpage = 1;		$offset = 0;		$rows = $this->M_shops_rows->gets($args, $perpage, $offset);		$max_order = isset($rows[0]['order']) ? $rows[0]['order'] : 0;		return (int) $max_order;	}	function re_order() {		$args = $this->default_args();		$order_by = array(			'order' => 'ASC',		);		$args['order_by'] = $order_by;		$rows = $this->M_shops_rows->gets($args);		if (!empty($rows)) {			$i = 0;			foreach ($rows as $value) {				$i++;				$data = array(					'order' => $i,				);				$this->M_shops_rows->update($value['id'], $data);			}		}	}	function check_product_code_availablity() {		$this->load->model('shops/m_shops_rows', 'M_shops_rows');		$post = $this->input->post();		$this->_message_success = 'Bạn có thể sử dụng mã này!';		$this->_message_danger = 'Mã này đã tồn tại!';		if (!empty($post)) {			if ($this->input->post('ajax') == '1') {				$product_code = $this->input->post('product_code');				if ($this->M_shops_rows->check_product_code_availablity($product_code)) {					$this->_status = "success";					$this->_message = $this->_message_success;				} else {					$this->_status = "danger";					$this->_message = $this->_message_danger;				}				$this->set_json_encode();				$this->load->view('layout/json_data', $this->_data);			} else {				$product_code = $this->input->post('product_code');				if ($this->M_shops_rows->check_product_code_availablity($product_code)) {					return TRUE;				} else {					return FALSE;				}			}		} else {			redirect(base_url());		}	}	function get_all_data() {		return $this->M_shops_rows->gets(array());	}	function get_products_bestsellers($limit = 3) {		$this->load->model('m_shops_order_details', 'M_shops_order_details');		$rows = $this->M_shops_order_details->get_best_seller($limit);		$result = array();		foreach ($rows as $value) {			$arr = array();			$arr = $this->get($value['product_id']);			$result[] = $arr;		}		return $result;	}	function get_top_4_rows($number = 4) {		$order_by = array(			'addtime' => 'DESC',		);		$args['order_by'] = $order_by;		return $this->M_shops_rows->gets($args, $number, 0);	}	function get_view_most($number = 4) {		$order_by = array(			'hitstotal' => 'DESC',		);		$args['order_by'] = $order_by;		return $this->M_shops_rows->gets($args, $number, 0);	}	function get_items_is_featured($limit = 8) {		$args = $this->default_args();		$args['is_featured'] = 1;		$args['status'] = 1;		if ($limit > 0) {			$rows = $this->M_shops_rows->gets($args, $limit, 0);		} else {			$rows = $this->M_shops_rows->gets($args);		}		return $rows;	}	function site_details() {		$this->_initialize();		$uri = explode("-", ($this->uri->segment(3) == '') ? '' : $this->uri->segment(3));		if (count($uri) <= 1) {			show_404();		}		$id = (int) end($uri);		array_pop($uri);		$alias = implode("-", $uri);		if ($id == 0 || $alias == '') {			show_404();		}		$row = $this->get($id);		if (!empty($row)) {			$title_seo = trim($row['title_seo']) != '' ? $row['title_seo'] : $row['title'];			$keywords = $row['keywords'];			$description = $row['description'];			$other_seo = $row['other_seo'];			if (trim($title_seo) != '') {				$this->_data['title_seo'] = $title_seo . ' - ' . $this->_data['title_seo'];			}			if (trim($keywords) != '') {				$this->_data['keywords'] = $keywords;			}			if (trim($description) != '') {				$this->_data['description'] = $description;			}			if (trim($other_seo) != '') {				$this->_data['other_seo'] = $other_seo;			}            $this->_data['image'] = get_image(get_module_path('shops') . $row['homeimgfile'], get_module_path('logo') . $this->_data['site_image']);		} else {			show_404();		}		$this->_breadcrumbs[] = array(			'url' => site_url($this->config->item('url_shops_rows')),			'name' => 'Sản phẩm',		);		$this->_breadcrumbs[] = array(			'url' => site_url($this->config->item('url_shops_cat') . '/' . $row['cat_alias']),			'name' => $row['cat_name'],		);		$this->_breadcrumbs[] = array(			'url' => site_url($this->config->item('url_shops_rows') . '/' . $row['cat_alias'] . '/' . $row['alias'] . '-' . $row['id']),			'name' => $row['title'],		);		$this->set_breadcrumbs();		//tags		$tags = modules::run('tags/tags_relationship/get_data_by_object_id', $row['id'], $this->_tag);		$row['tags'] = array_column($tags, 'name', 'alias');		$this->_data['h1_seo'] = $row['h1_seo'];		$hitstotal = (int) $row['hitstotal'] + 1;		$this->site_update_view($row['id'], $hitstotal);		$this->_data['row'] = $row;		$rows = $this->M_shops_rows->gets(array(			'cat_id' => $row['listcatid'],			'not_in_id' => $row['id'],		), 12, 0);		//render partial		$partial = array();		$partial['data'] = $rows;		$this->_data['related_products'] = $this->load->view('layout/site/partial/product_related', $partial, true);		/*					$this->_add_js[] = 'custom-single-shop';			        $this->add_js();		*/		$this->_data['main_content'] = 'layout/site/pages/single-shop';		$this->load->view('layout/site/layout', $this->_data);	}	function index() {		$this->_initialize();		$this->output->cache(true);		$shops_cat = modules::run('shops/cat/gets', true);		if (is_array($shops_cat) && !empty($shops_cat)) {			foreach ($shops_cat as $key => $value) {				$shops_cat[$key]['items'] = $this->get_items_in_cat_id($value['id'], 0);			}		}		$partial = array();		$partial['data'] = $shops_cat;		$this->_data['rows'] = $this->load->view('layout/site/partial/product_collection', $partial, true);		$this->_breadcrumbs[] = array(			'url' => site_url($this->config->item('url_shops_rows')),			'name' => 'Sản phẩm',		);		$this->set_breadcrumbs();		$this->_data['title_seo'] = 'Sản phẩm' . ' - ' . $this->_data['title_seo'];		$this->_data['main_content'] = 'layout/site/pages/shops';		$this->load->view('layout/site/layout', $this->_data);	}	function site_search() {		$this->_initialize();		$get = $this->input->get();		$this->_data['get'] = $get;		if (!isset($get['q']) || trim($get['q']) == '') {			redirect(base_url());		}		$args = $this->default_args();		$args['q'] = $get['q'];		$total = $this->counts($args);		$perpage = 12; //$this->config->item('per_page') ? $this->config->item('per_page') : 10;		$segment = 2;		$this->load->library('pagination');		$config['total_rows'] = $total;		$config['per_page'] = $perpage;		$config['full_tag_open'] = '<ul class="pagination">';		$config['full_tag_close'] = '</ul><!--pagination-->';		$config['first_link'] = '&larr;';		$config['first_tag_open'] = '<li class="prev page">';		$config['first_tag_close'] = '</li>';		$config['last_link'] = '&rarr;';		$config['last_tag_open'] = '<li class="next page">';		$config['last_tag_close'] = '</li>';		$config['next_link'] = '&raquo;';		$config['next_tag_open'] = '<li class="next page">';		$config['next_tag_close'] = '</li>';		$config['prev_link'] = '&laquo;';		$config['prev_tag_open'] = '<li class="prev page">';		$config['prev_tag_close'] = '</li>';		$config['cur_tag_open'] = '<li class="active"><a href="">';		$config['cur_tag_close'] = '</a></li>';		$config['num_tag_open'] = '<li class="page">';		$config['num_tag_close'] = '</li>';		$config['base_url'] = base_url('search');		$config['suffix'] = '?' . http_build_query($get, '', "&");		$config['first_url'] = site_url('search') . '?' . http_build_query($get, '', "&");		$config['uri_segment'] = $segment;		$this->pagination->initialize($config);		$pagination = $this->pagination->create_links();		$offset = ($this->uri->segment($segment) == '') ? 0 : $this->uri->segment($segment);		$rows = $this->M_shops_rows->gets($args, $perpage, $offset);		$this->_data['pagination'] = $pagination;		$partial = array();		$partial['data'] = $rows;		$this->_data['rows'] = $this->load->view('layout/site/partial/product', $partial, true);		$this->_breadcrumbs[] = array(			'url' => current_url(),			'name' => 'Tìm kiếm',		);		$this->set_breadcrumbs();		$this->_data['title_seo'] = 'Kết quả tìm kiếm' . ' - ' . $this->_data['title_seo'];		$this->_data['main_content'] = 'layout/site/pages/search-shop';		$this->load->view('layout/site/layout', $this->_data);	}	function counts_all() {		return $this->counts(array());	}	function site_items_tag() {		$this->_initialize();		$segment = 2;		$tag_slug = ($this->uri->segment($segment) == '') ? '' : $this->uri->segment($segment);		if (trim($tag_slug) == '') {			redirect(base_url());		}		$row = modules::run('tags/get_by', array('alias' => $tag_slug));		if (isset($row['id'])) {			$tag_id = $row['id'];		} else {			redirect(base_url());		}		$data = modules::run('tags/tags_relationship/gets', array('tag_id' => $tag_id, 'module' => $this->_tag));		if (empty($data)) {			$in_id = array(0);		} else {			$in_id = array_column($data, 'object_id');		}		$this->output->cache(true);		$this->_data['title_seo'] = 'Từ khóa "' . $tag_slug . '" - ' . $this->_data['title_seo'];		$args = $this->default_args();		$args['in_id'] = $in_id;		$total = $this->counts($args);		$perpage = 12;		$this->load->library('pagination');		$config['total_rows'] = $total;		$config['per_page'] = $perpage;		$config['full_tag_open'] = '<ul class="pagination">';		$config['full_tag_close'] = '</ul><!--pagination-->';		$config['first_link'] = '&laquo;';		$config['first_tag_open'] = '<li class="prev page">';		$config['first_tag_close'] = '</li>';		$config['last_link'] = '&raquo;';		$config['last_tag_open'] = '<li class="next page">';		$config['last_tag_close'] = '</li>';		$config['next_link'] = '&rarr;';		$config['next_tag_open'] = '<li class="next page">';		$config['next_tag_close'] = '</li>';		$config['prev_link'] = '&larr;';		$config['prev_tag_open'] = '<li class="prev page">';		$config['prev_tag_close'] = '</li>';		$config['cur_tag_open'] = '<li class="active"><a href="">';		$config['cur_tag_close'] = '</a></li>';		$config['num_tag_open'] = '<li class="page">';		$config['num_tag_close'] = '</li>';		$segment++;		$config['base_url'] = base_url('tag/' . $tag_slug);		$config['uri_segment'] = $segment;		$config['first_url'] = site_url('tag/' . $tag_slug);		$this->pagination->initialize($config);		$pagination = $this->pagination->create_links();		$offset = ($this->uri->segment($segment) == '') ? 0 : $this->uri->segment($segment);		$this->_data['pagination'] = $pagination;		$rows = $this->M_shops_rows->gets($args, $perpage, $offset);		$partial = array();		$partial['data'] = null;		if (!empty($rows)) {			foreach ($rows as $value) {				$partial['data'][] = $this->get($value['id'], $value['alias']);			}		}		$this->_data['rows'] = $this->load->view('layout/site/partial/product', $partial, true);		$this->_data['row'] = $row;		$this->_breadcrumbs[] = array(			'url' => $config['first_url'],			'name' => 'Từ khóa: "' . $row['name'] . '"',		);		$this->set_breadcrumbs();		$this->_data['main_content'] = 'layout/site/pages/tag-shops';		$this->load->view('layout/site/layout', $this->_data);	}	function site_items_in_listcatid() {		$this->_initialize();		$segment = 2;		$cat_alias = ($this->uri->segment($segment) == '') ? '' : $this->uri->segment($segment);		if (trim($cat_alias) == '') {			show_404();		}		$data = modules::run('shops/cat/get_in_alias', $cat_alias);		if (empty($data)) {			show_404();		}		$this->output->cache(true);		$this->_data['image'] = get_image(get_module_path('shops_cat') . $data['image'], get_module_path('logo') . $this->_data['site_image']);		$get = $this->input->get();		$this->_data['get'] = $get;		$collection = modules::run('shops/cat/gets_data', array());		$this->_data['collection'] = $collection;		$filter = modules::run('shops/filter/gets', array('in_id' => explode(',', $data['filter'])));		$this->_data['filter'] = $filter;		$cat_id = $data['id'];		$in_cat_id[] = $cat_id;		$cat = modules::run('shops/cat/gets');		$in_cat_id = array_merge($in_cat_id, get_children($cat_id, $cat['data_list'], $cat['data_input']));		$title_seo = trim($data['title_seo']) != '' ? $data['title_seo'] : $data['name'];		$keywords = $data['keywords'];		$description = $data['description'];		$other_seo = $data['other_seo'];		if (trim($title_seo) != '') {			$this->_data['title_seo'] = $title_seo . ' - ' . $this->_data['title_seo'];		}		if (trim($keywords) != '') {			$this->_data['keywords'] = $keywords;		}		if (trim($description) != '') {			$this->_data['description'] = $description;		}		if (trim($other_seo) != '') {			$this->_data['other_seo'] = $other_seo;		}		$args = $this->default_args();		$args['in_cat_id'] = $in_cat_id;		if(isset($get['filter'])){			$filter_id = $get['filter'];			//filter			$data_filter_details = modules::run('shops/filter_details/gets', array('filter_id' => $filter_id));			$in_id = array(-1);			if(is_array($data_filter_details) && !empty($data_filter_details)){				$in_id = array_column($data_filter_details, 'product_id');			}			$args['in_id'] = $in_id;		}		if(isset($get['sort_by'])){			switch ($get['sort_by']) {				case 'manual':					$args['order_by'] = array(						'order' => 'DESC',					);					break;				case 'best-selling':					$args['order_by'] = array(						'order' => 'DESC',					);					break;				case 'title-ascending':					$args['order_by'] = array(						'title' => 'ASC',					);					break;				case 'title-descending':					$args['order_by'] = array(						'title' => 'DESC',					);					break;				case 'price-ascending':					$args['order_by'] = array(						'product_price' => 'ASC',					);					break;				case 'price-descending':					$args['order_by'] = array(						'product_price' => 'DESC',					);					break;				case 'created-descending':					$args['order_by'] = array(						'addtime' => 'DESC',					);					break;				case 'created-ascending':					$args['order_by'] = array(						'addtime' => 'ASC',					);					break;				default:					break;			}		}		$total = $this->counts($args);		$perpage = 12;		$this->load->library('pagination');		$config['total_rows'] = $total;		$config['per_page'] = $perpage;		$config['full_tag_open'] = '<ul class="pagination">';		$config['full_tag_close'] = '</ul><!--pagination-->';		$config['first_link'] = '&larr;';		$config['first_tag_open'] = '<li class="prev page">';		$config['first_tag_close'] = '</li>';		$config['last_link'] = '&rarr;';		$config['last_tag_open'] = '<li class="next page">';		$config['last_tag_close'] = '</li>';		$config['next_link'] = '&raquo;';		$config['next_tag_open'] = '<li class="next page">';		$config['next_tag_close'] = '</li>';		$config['prev_link'] = '&laquo;';		$config['prev_tag_open'] = '<li class="prev page">';		$config['prev_tag_close'] = '</li>';		$config['cur_tag_open'] = '<li class="active"><a href="">';		$config['cur_tag_close'] = '</a></li>';		$config['num_tag_open'] = '<li class="page">';		$config['num_tag_close'] = '</li>';		$segment++;		$config['base_url'] = base_url($this->config->item('url_shops_cat') . '/' . $cat_alias);		$config['uri_segment'] = $segment;		$config['first_url'] = site_url($this->config->item('url_shops_cat') . '/' . $cat_alias);		$this->pagination->initialize($config);		$pagination = $this->pagination->create_links();		$offset = ($this->uri->segment($segment) == '') ? 0 : $this->uri->segment($segment);		$rows = $this->M_shops_rows->gets($args, $perpage, $offset);		$this->_data['pagination'] = $pagination;		$partial = array();		$partial['data'] = null;		if (!empty($rows)) {			foreach ($rows as $value) {				$partial['data'][] = $this->get($value['id'], $value['alias']);			}		}		$this->_data['rows'] = $this->load->view('layout/site/partial/product', $partial, true);		$cat_title = $data['name'];		$this->_data['row'] = $data;		$this->_breadcrumbs[] = array(			'url' => site_url($this->config->item('url_shops_rows')),			'name' => 'Sản phẩm',		);		$this->_breadcrumbs[] = array(			'url' => $config['first_url'],			'name' => $cat_title,		);		$this->set_breadcrumbs();		$this->_data['main_content'] = 'layout/site/pages/cat-shops';		$this->load->view('layout/site/layout', $this->_data);	}	function get_items_in_cat_id($cat_id = 0, $limit = 8) {		$in_cat_id[] = $cat_id;		$cat = modules::run('shops/cat/gets');		$in_cat_id = array_merge($in_cat_id, get_children($cat_id, $cat['data_list'], $cat['data_input']));		$args = $this->default_args();		$args['in_cat_id'] = $in_cat_id;		if ($limit > 0) {			$rows = $this->M_shops_rows->gets($args, $limit, 0);		} else {			$rows = $this->M_shops_rows->gets($args);		}		return $rows;	}	function admin_index() {		$this->_initialize_admin();		$this->redirect_admin();		$this->_plugins_css_admin[] = array(			'folder' => 'bootstrap3-dialog/css',			'name' => 'bootstrap-dialog',		);		$this->_plugins_script_admin[] = array(			'folder' => 'bootstrap3-dialog/js',			'name' => 'bootstrap-dialog',		);		$this->set_plugins_admin();		$this->_init_fancybox();		$this->_modules_script[] = array(			'folder' => 'shops',			'name' => 'admin-items',		);		$this->set_modules();		$get = $this->input->get();		$this->_data['get'] = $get;		$args = $this->default_args();		$order_by = array(			'order' => 'DESC',			'title' => 'ASC',			'addtime' => 'DESC',			'edittime' => 'DESC',		);		$args['order_by'] = $order_by;		$shops_cat = modules::run('shops/cat/gets');		$this->_data['shops_cat'] = $shops_cat;		if (isset($get['catid']) && ($get['catid'] != 0)) {			$catid = $get['catid'];			$listcatid[] = (int) $catid;			$listcatid = array_merge($listcatid, get_children($catid, $shops_cat['data_list'], $shops_cat['data_input']));			$args['in_cat_id'] = $listcatid;		}		if (isset($get['q']) && trim($get['q']) != '') {			$args['q'] = $get['q'];		}		$total = $this->counts($args);		$perpage = isset($get['per_page']) ? $get['per_page'] : $this->config->item('per_page');		$segment = 4;		$this->load->library('pagination');		$config['total_rows'] = $total;		$config['per_page'] = $perpage;		$config['full_tag_open'] = '<ul class="pagination no-margin pull-right">';		$config['full_tag_close'] = '</ul><!--pagination-->';		$config['first_link'] = '&laquo;';		$config['first_tag_open'] = '<li class="prev page">';		$config['first_tag_close'] = '</li>';		$config['last_link'] = '&raquo;';		$config['last_tag_open'] = '<li class="next page">';		$config['last_tag_close'] = '</li>';		$config['next_link'] = 'Trang trước &rarr;';		$config['next_tag_open'] = '<li class="next page">';		$config['next_tag_close'] = '</li>';		$config['prev_link'] = '&larr; Trang sau';		$config['prev_tag_open'] = '<li class="prev page">';		$config['prev_tag_close'] = '</li>';		$config['cur_tag_open'] = '<li class="active"><a href="">';		$config['cur_tag_close'] = '</a></li>';		$config['num_tag_open'] = '<li class="page">';		$config['num_tag_close'] = '</li>';		if (!empty($get)) {			$config['base_url'] = get_admin_url($this->_module_slug);			$config['suffix'] = '?' . http_build_query($get, '', "&");			$config['first_url'] = get_admin_url($this->_module_slug . '?' . http_build_query($get, '', "&"));			$config['uri_segment'] = $segment;		} else {			$config['base_url'] = get_admin_url($this->_module_slug);			$config['uri_segment'] = $segment;		}		$this->pagination->initialize($config);		$pagination = $this->pagination->create_links();		$offset = ($this->uri->segment($segment) == '') ? 0 : $this->uri->segment($segment);		$rows = $this->M_shops_rows->gets($args, $perpage, $offset);		$this->_data['rows'] = $rows;		$this->_data['pagination'] = $pagination;		$this->_data['title'] = 'Danh sách sản phẩm - ' . $this->_data['title'];		$this->_data['main_content'] = 'shops/admin/view_page_index';		$this->load->view('layout/admin/view_layout', $this->_data);	}	function admin_add() {		$data = array(			'listcatid' => $this->input->post('catid'),			'user_id' => $this->_data['userid'],			'addtime' => time(),			'edittime' => 0,			'status' => 1,			'is_bestseller' => $this->input->post('is_bestseller') ? 1 : 0,			'is_featured' => $this->input->post('is_featured') ? 1 : 0,			'is_new' => $this->input->post('is_new') ? 1 : 0,			'inhome' => $this->input->post('inhome') ? 1 : 0,			'is_have_buy' => $this->input->post('is_have_buy') ? 1 : 0,			'title' => $this->input->post('title'),			'alias' => $this->input->post('alias'),			'stock_status' => $this->input->post('stock_status'),			'title_seo' => $this->input->post('title_seo'),			'description' => $this->input->post('description'),			'keywords' => $this->input->post('keywords'),			'other_seo' => $this->input->post('other_seo'),			'h1_seo' => $this->input->post('h1_seo'),			'homeimgalt' => $this->input->post('homeimgalt'),			'hometext' => $this->input->post('hometext'),			'bodyhtml' => $this->input->post('bodyhtml'),			'product_code' => $this->input->post('product_code'),			'product_price' => filter_var($this->input->post('product_price'), FILTER_SANITIZE_NUMBER_INT),			'product_sales_price' => filter_var($this->input->post('product_sales_price'), FILTER_SANITIZE_NUMBER_INT),			'order' => $this->get_max_order() + 1,		);		return $this->M_shops_rows->add($data);	}	function site_update_view($id = 0, $view) {		$data = array('hitstotal' => $view);		return $this->M_shops_rows->update($id, $data);	}	function admin_update($id) {		$data = array(			'listcatid' => $this->input->post('catid'),			'edittime' => time(),			'is_bestseller' => $this->input->post('is_bestseller') ? 1 : 0,			'is_featured' => $this->input->post('is_featured') ? 1 : 0,			'is_new' => $this->input->post('is_new') ? 1 : 0,			'inhome' => $this->input->post('inhome') ? 1 : 0,			'is_have_buy' => $this->input->post('is_have_buy') ? 1 : 0,			'title' => $this->input->post('title'),			'alias' => $this->input->post('alias'),			'stock_status' => $this->input->post('stock_status'),			'title_seo' => $this->input->post('title_seo'),			'description' => $this->input->post('description'),			'keywords' => $this->input->post('keywords'),			'other_seo' => $this->input->post('other_seo'),			'h1_seo' => $this->input->post('h1_seo'),			'homeimgalt' => $this->input->post('homeimgalt'),			'hometext' => $this->input->post('hometext'),			'bodyhtml' => $this->input->post('bodyhtml'),			'product_code' => $this->input->post('product_code'),			'product_price' => filter_var($this->input->post('product_price'), FILTER_SANITIZE_NUMBER_INT),			'product_sales_price' => filter_var($this->input->post('product_sales_price'), FILTER_SANITIZE_NUMBER_INT),		);		return $this->M_shops_rows->update($id, $data);	}	function admin_delete() {		$this->_initialize_admin();		$this->redirect_admin();		$this->_message_success = 'Đã xóa sản phẩm!';		$this->_message_warning = 'Sản phẩm này không tồn tại!';		$id = $this->input->get('id');		if ($id != 0) {			$row = $this->get($id);			if ($this->M_shops_rows->delete($id)) {				@unlink(FCPATH . $this->_path . $row['homeimgfile']);				if (isset($row['options']) && is_array($row['options']) && !empty($row['options'])) {					foreach ($row['options'] as $value) {						@unlink(FCPATH . $this->_path . $value['image']);					}					modules::run('shops/other/delete', array('product' => $id));				}				//sap xep lai				$this->re_order();				modules::run('tags/delete', 'shops', $id);				$notify_type = 'success';				$notify_content = $this->_message_success;			} else {				$notify_type = 'danger';				$notify_content = $this->_message_danger;			}		} else {			$notify_type = 'warning';			$notify_content = $this->_message_warning;		}		$this->set_notify_admin($notify_type, $notify_content);		redirect(get_admin_url($this->_module_slug));	}	function admin_main() {		$this->_initialize_admin();		$this->redirect_admin();		$post = $this->input->post();		if (!empty($post)) {			$action = $this->input->post('action');			if ($action == 'delete') {				$this->_message_success = 'Đã xóa các sản phẩm được chọn!';				$this->_message_warning = 'Bạn chưa chọn sản phẩm nào!';				$ids = $this->input->post('idcheck');				if (is_array($ids) && !empty($ids)) {					foreach ($ids as $id) {						$row = $this->get($id);						if ($this->M_shops_rows->delete($id)) {							@unlink(FCPATH . $this->_path . $row['homeimgfile']);							if (isset($row['options']) && is_array($row['options']) && !empty($row['options'])) {								foreach ($row['options'] as $value) {									@unlink(FCPATH . $this->_path . $value['image']);								}								modules::run('shops/other/delete', array('product' => $id));							}							modules::run('tags/delete', 'shops', $id);							$notify_type = 'success';							$notify_content = $this->_message_success;						} else {							$notify_type = 'danger';							$notify_content = $this->_message_danger;						}					}					//sap xep lai					$this->re_order();				} else {					$notify_type = 'warning';					$notify_content = $this->_message_warning;				}				$this->set_notify_admin($notify_type, $notify_content);				redirect(get_admin_url($this->_module_slug));			} elseif ($action == 'content') {				redirect(get_admin_url('shops/content'));			} elseif ($action == 'update') {				$this->_message_success = 'Đã cập nhật sản phẩm!';				$this->_message_warning = 'Không có sản phẩm nào để cập nhật!';				$ids = $this->input->post('ids');				$orders = $this->input->post('order');				$count = count($orders);				if (!empty($ids) && !empty($orders)) {					for ($i = 0; $i < $count; $i++) {						$data = array(							'order' => $orders[$i],						);						$id = $ids[$i];						if ($this->M_shops_rows->update($id, $data)) {							$notify_type = 'success';							$notify_content = $this->_message_success;							$this->output->clearCache();						} else {							$notify_type = 'danger';							$notify_content = $this->_message_danger;						}					}				} else {					$notify_type = 'warning';					$notify_content = $this->_message_warning;				}				$this->set_notify_admin($notify_type, $notify_content);				redirect(get_admin_url($this->_module_slug));			}		} else {			redirect(get_admin_url($this->_module_slug));		}	}	function admin_content() {		$this->_initialize_admin();		$this->redirect_admin();		$this->_plugins_script_admin[] = array(			'folder' => 'jquery-validation',			'name' => 'jquery.validate',		);		$this->_plugins_script_admin[] = array(			'folder' => 'jquery-validation/localization',			'name' => 'messages_vi',		);		$this->_plugins_css_admin[] = array(			'folder' => 'tagmanager',			'name' => 'tagmanager',		);		$this->_plugins_script_admin[] = array(			'folder' => 'tagmanager',			'name' => 'tagmanager',		);		$this->_plugins_script_admin[] = array(			'folder' => 'jquery-mask',			'name' => 'jquery.mask',		);		$this->_plugins_css_admin[] = array(			'folder' => 'bootstrap-fileinput/css',			'name' => 'fileinput',		);		$this->_plugins_script_admin[] = array(			'folder' => 'bootstrap-fileinput/js',			'name' => 'fileinput.min',		);		$this->_plugins_css_admin[] = array(            'folder' => 'chosen',            'name' => 'chosen'        );        $this->_plugins_script_admin[] = array(            'folder' => 'chosen',            'name' => 'chosen.jquery'        );        $this->_plugins_script_admin[] = array(            'folder' => 'chosen',            'name' => 'apps'        );		$this->set_plugins_admin();		$this->_modules_script[] = array(			'folder' => 'shops',			'name' => 'admin-content-validate',		);		$this->set_modules();		$post = $this->input->post();		if (!empty($post)) {			$this->load->helper('language');			$this->lang->load('form_validation', 'vietnamese');			$this->lang->load('cat', 'vietnamese');			$this->form_validation->set_error_delimiters('<span class="help-block">', '</span>');			$this->form_validation->set_rules('title', 'Tên sản phẩm', 'trim|required');			$this->form_validation->set_rules('alias', 'Liên kết tĩnh', 'trim|required');			if ($this->form_validation->run($this)) {				$data_filter = $this->input->post('filter');				if ($this->input->post('id')) {					$err = FALSE;					$id = $this->input->post('id');					if (!$this->admin_update($id)) {						$err = TRUE;					} else {						//upload images						$this->_upload_images($id, 'homeimg');						$this->_upload_images_options($id);						//filter						$data_filter_details = modules::run('shops/filter_details/gets', array('product_id' => $id));						$data_filter_details_current = (is_array($data_filter_details) && !empty($data_filter_details)) ? array_column($data_filter_details, 'filter_id', 'id') : array(-1);						$in_filter_id = array_diff((array)$data_filter_details_current, (array)$data_filter);						if(empty($in_filter_id)){							$in_filter_id = array(-1);						}						modules::run('shops/filter_details/delete', array('in_filter_id' => $in_filter_id));						if(is_array($data_filter) && !empty($data_filter)){							foreach($data_filter as $value){								if($value != 0){									$arr_validate_exist = array(										'product_id' => $id,										'filter_id' => $value,									);									if(modules::run('shops/filter_details/get', $arr_validate_exist)){										modules::run('shops/filter_details/update', $arr_validate_exist, array(											'modified' => time()										));									}else{										$arr_validate_exist['created'] = time();										$arr_validate_exist['modified'] = 0;										modules::run('shops/filter_details/add', $arr_validate_exist);									}									unset($arr_validate_exist);								}							}						}						//tags						$tags_value = $this->input->post('hidden-tags');						$arr_tags = explode(',', $tags_value);						if (is_array($arr_tags) && !empty($arr_tags)) {							$tags = modules::run('tags/tags_relationship/get_data_by_object_id', $id, $this->_tag);							$tags_id = array_column($tags, 'tag_id');							modules::run('tags/admin_delete', $tags_id);							modules::run('tags/tags_relationship/admin_delete_by_object_id', $id, $this->_tag);							foreach ($arr_tags as $value) {								$data_tags = array(									'name' => $value,									'alias' => strtolower(url_title(alias($value))),								);								$tag_id = modules::run('tags/admin_add', $data_tags);								//tags relationship								$data_tags_relationship = array(									'tag_id' => $tag_id,									'object_id' => $id,									'module' => $this->_tag,								);								modules::run('tags/tags_relationship/admin_add', $data_tags_relationship);							}						}					}					if ($err === FALSE) {						$this->output->clearCache();						$notify_type = 'success';						$notify_content = 'Cập nhật sản phẩm thành công!';						$this->set_notify_admin($notify_type, $notify_content);						redirect(get_admin_url($this->_module_slug));					} else {						$notify_type = 'danger';						$notify_content = 'Có lỗi xảy ra!';						$this->set_notify_admin($notify_type, $notify_content);					}				} else {//add					$err = FALSE;					$insert_id = $this->admin_add();					if ($insert_id == 0) {						$err = TRUE;					} else {						//upload images						$this->_upload_images($insert_id, 'homeimg');						$this->_upload_images_options($insert_id);						if(is_array($data_filter) && !empty($data_filter)){							foreach($data_filter as $value){								if($value != 0){									$arr_validate_exist = array(										'product_id' => $insert_id,										'filter_id' => $value,									);									if(modules::run('shops/filter_details/get', $arr_validate_exist)){										modules::run('shops/filter_details/update', $arr_validate_exist, array(											'modified' => time()										));									}else{										$arr_validate_exist['created'] = time();										$arr_validate_exist['modified'] = 0;										modules::run('shops/filter_details/add', $arr_validate_exist);									}									unset($arr_validate_exist);								}							}						}						//tags						$tags_value = $this->input->post('hidden-tags');						$arr_tags = explode(',', $tags_value);						if (is_array($arr_tags) && !empty($arr_tags)) {							foreach ($arr_tags as $value) {								$data_tags = array(									'name' => $value,									'alias' => strtolower(url_title(alias($value))),								);								$tag_id = modules::run('tags/admin_add', $data_tags);								//tags relationship								$data_tags_relationship = array(									'tag_id' => $tag_id,									'object_id' => $insert_id,									'module' => $this->_tag,								);								modules::run('tags/tags_relationship/admin_add', $data_tags_relationship);							}						}					}					if ($err === FALSE) {						$this->output->clearCache();						$notify_type = 'success';						$notify_content = 'Sản phẩm đã được thêm!';						$this->set_notify_admin($notify_type, $notify_content);						redirect(get_admin_url($this->_module_slug));					} else {						$notify_type = 'danger';						$notify_content = 'Có lỗi xảy ra!';						$this->set_notify_admin($notify_type, $notify_content);					}				}			}		}		$this->load->library('ckeditor', array('instanceName' => 'CKEDITOR1', 'basePath' => base_url() . "ckeditor/", 'outPut' => true));		$title = 'Thêm sản phẩm - ' . $this->_data['breadcrumbs_module_name'] . ' - ' . $this->_data['title'];		$is_temp = modules::run('shops/other/gets', array('is_temp' => 1));		if (is_array($is_temp) && !empty($is_temp)) {			foreach ($is_temp as $value) {				@unlink(FCPATH . $this->_path . $value['image']);			}			modules::run('shops/other/delete', array('is_temp' => 1));		}		$args_filter = array('in_id' => array(-1));		$id = ($this->uri->segment(4) == '') ? 0 : $this->uri->segment(4);		if ($id != 0) {			$row = $this->get($id);			$tags = modules::run('tags/tags_relationship/get_data_by_object_id', $row['id'], $this->_tag);			$row['tags'] = implode(',', array_column($tags, 'name'));			//filter			$data_filter_details = modules::run('shops/filter_details/gets', array('product_id' => $id));			$row['filter'] = array_column($data_filter_details, 'filter_id');			$this->_data['row'] = $row;			$title = 'Cập nhật sản phẩm - ' . $this->_data['breadcrumbs_module_name'] . ' - ' . $this->_data['title'];			$cat_filter = explode(',', $row['cat_filter']);			$in_filter_id = array(-1);			if(is_array($cat_filter) && !empty($cat_filter)){				$in_filter_id = $cat_filter;			}			$args_filter = array('in_id' => $in_filter_id);		}		$this->_data['shops_cat'] = modules::run('shops/cat/gets');		$filter = modules::run('shops/filter/gets', $args_filter);		$this->_data['filter'] = $filter;		$this->_data['title'] = $title;		$this->_data['main_content'] = 'shops/admin/view_page_content';		$this->load->view('layout/admin/view_layout', $this->_data);	}	public function admin_get_price_ajax() {		$this->_data['order'] = (int) $this->input->post('order') + 1;		$this->_data['shops_unit'] = modules::run('shops/unit/gets');		$this->load->view('shops/admin/view_price', $this->_data);	}	public function ajax_get_items_in_catid() {		$catid = $this->input->post('catid');		$id = $this->input->post('id');		$row = $this->M_shops_rows->get($id);		$this->_data['row'] = $row;		$args = array();		$args['in_cat_id'] = $catid;		$this->_data['rows'] = $this->M_shops_rows->gets($args);		$this->load->view('shops/admin/view_related', $this->_data);	}	private function _upload_images($id, $input_name) {		//$watermark_image = get_module_path('logo') . modules::run('configs/get_config_value', 'watermark_image');		//$watermark_opacity = modules::run('configs/get_config_value', 'watermark_opacity');		$row = $this->get($id);		$info = modules::run('files/index', $input_name, $this->_path);		if (isset($info['uploads'])) {			$upload_images = $info['uploads']; // thông tin ảnh upload			if ($_FILES[$input_name]['size'] != 0) {				foreach ($upload_images as $value) {					$file_name = $value['file_name']; //tên ảnh					$data_images = array(						'homeimgfile' => $file_name,					);					$this->M_shops_rows->update($id, $data_images);					//modules::run('files/watermark_overlay', './' . $this->_path . $file_name, './' . $watermark_image, array('wm_opacity' => $watermark_opacity));				}				@unlink(FCPATH . $this->_path . $row['homeimgfile']);			}		}	}	private function _upload_images_options($id) {		$option_ids = $this->input->post('option_id');		if (is_array($option_ids) && !empty($option_ids)) {			modules::run('shops/other/update', array('in_id' => $option_ids), array(				'product' => $id,				'is_temp' => 0,				'edittime' => time(),			));		}	}	function ajax_upload() {		$name_input = 'files';		$dir = $this->_path;		$options = array();		$options['allowed_types'] = "gif|jpg|jpeg|png";		$this->_upload($name_input, $dir, $options);	}	function _upload($name_input = 'file', $dir = 'uploads/', $options = array()) {		if (!$this->input->is_ajax_request()) {			exit('No direct script access allowed');		}		$message = array();		$message['status'] = 'warning';		$message['content'] = null;		$message['message'] = 'Kiểm tra thông tin nhập';		$data_success = array();		$data_temp = array();		$data_error = array();		//$watermark_image = get_module_path('logo') . modules::run('configs/get_config_value', 'watermark_image');		//$watermark_opacity = modules::run('configs/get_config_value', 'watermark_opacity');		if (isset($_FILES[$name_input])) {			$product = filter_var($this->input->post('product'), FILTER_SANITIZE_NUMBER_INT);			$order = $this->input->post('order');			$number_of_files = sizeof($_FILES[$name_input]['tmp_name']);			$files = $_FILES[$name_input];			$this->load->library('upload');			$config['upload_path'] = FCPATH . $dir;			$config['max_size'] = '1024*10';			if (isset($options['allowed_types']) && trim($options['allowed_types']) != '') {				$config['allowed_types'] = $options['allowed_types'];			} else {				$config['allowed_types'] = '*'; //default			}			for ($i = 0; $i < $number_of_files; $i++) {				$_FILES[$name_input]['name'] = $files['name'][$i];				$_FILES[$name_input]['type'] = $files['type'][$i];				$_FILES[$name_input]['tmp_name'] = $files['tmp_name'][$i];				$_FILES[$name_input]['error'] = $files['error'][$i];				$_FILES[$name_input]['size'] = $files['size'][$i];				$name = alias(pathinfo($files['name'][$i], PATHINFO_FILENAME));				$config['file_name'] = $name;				$ext = pathinfo($files['name'][$i], PATHINFO_EXTENSION);				$this->upload->initialize($config);				$file_name = $name . '.' . $ext;				if ($this->upload->do_upload($name_input)) {					$data_success[] = $file_name;					$temp_id = modules::run('shops/other/add', array(						'product' => $product,						'image' => $file_name,						'alt' => '',						'order' => $order + $i + 1,						'is_temp' => 1,						'addtime' => time(),						'edittime' => 0,					));					$data_temp[] = modules::run('shops/other/get', array('id' => $temp_id));					//modules::run('files/watermark_overlay', './' . $this->_path . $file_name, './' . $watermark_image, array('wm_opacity' => $watermark_opacity));				} else {					$data_error[] = strip_tags($file_name . " has error: " . $this->upload->display_errors());				}			}			$status = FALSE;			if (!empty($data_success)) {				$message['content']['success'] = $this->load->view('admin/view_image', array('data' => $data_temp, 'order' => $order), TRUE);				$status = TRUE;			}			if (!empty($data_error)) {				$message['content']['error'] = implode(', ', $data_error);				$status = TRUE;			}			if ($status) {				$message['status'] = 'success';				$message['message'] = 'Xử lý dữ liệu thành công!';			}		}		echo json_encode($message);		exit();	}}/* End of file Rows.php *//* Location: ./application/modules/shops/controllers/Rows.php */